types.SceIoIob:
/* iofilemgr file descriptor block (first 0x20 bytes) */
typedef struct SceIoIob {
    s32 i_flgs; /* 0x0 */
    s32 i_unit; /* 0x4 */
    void *i_de; /* 0x8 */
    s32 d_type; /* 0xC */
    void *i_private; /* 0x10 */
    void *i_cwd; /* 0x14 */
    SceOff i_fpos; /* 0x18 */
} SceIoIob;

types.SceUmd9660BlkOps:
/* sceBLKRegister operations (g_umd9660BlkOps[2], 0x88 bytes) */
typedef struct {
    u32 attr; /* 0x00: 0x80000003 */
    s32 (*open)(void *, void *, s32 *); /* 0x04 */
    s32 (*sync)(void); /* 0x08 */
    void *unkC[0x1D]; /* 0x0C */
    s32 (*close)(void *, void *, s32 *); /* 0x80 */
    void *gp; /* 0x84 */
} SceUmd9660BlkOps;

types.SceUmd9660DevctlArgs:
/* umd9660_exec_devctl arguments for sceKernelExtendKernelStack */
typedef struct {
    SceIoIob *iob; /* 0x00 */
    s32 cmd; /* 0x04 */
    SceSize inlen; /* 0x08 */
    SceSize outlen; /* 0x0C */
    const char *name; /* 0x10 */
    void *indata; /* 0x14 */
    void *outdata; /* 0x18 */
    SceUmd9660Drive *drive; /* 0x1C */
} SceUmd9660DevctlArgs;

types.SceUmd9660Drive:
/* one per unit (g_umd9660Drives[2], 0x864 bytes in 1.00, 0x868 in 1.02+); the sceBLK device data */
typedef struct {
    u8 sectorBuf[0x800]; /* 0x000 */
    char name[0x20]; /* 0x800: "umd%01x:" (sceBLKRegister name) */
    union {
        SceUID semaId; /* 0x820 */
        s32 unk820[4]; /* 0x820: [1] = -1, [2] = 1 at init (an array: Init/BLK close index it) */
    };
    s32 unk830[3]; /* 0x830: [2] = BLK open count */
    SceUmd9660DiscInfo disc; /* 0x83C */
    struct SceUmdDrive *umdDrive; /* 0x860 (1.02+: 0x864) */
} SceUmd9660Drive;
typedef char chk_SceUmd9660Drive[(sizeof(SceUmd9660Drive) == ((FW_VERSION == 100) ? 0x864 : 0x868)) ? 1 : -1];

types.SceUmd9660File:
/* open file (g_umd9660Files[maxFiles], 0x60 bytes) */
typedef struct {
    u64 pos; /* 0x00: current sector */
    char devName[0x20]; /* 0x08 */
    char path[0x20]; /* 0x28 */
    s32 state; /* 0x48: 1 = free, 0x80 = allocated */
    s32 mode; /* 0x4C: (flags >> 16) & 0xF */
    u32 numSectors; /* 0x50 */
    u32 size; /* 0x54: numSectors * 0x800 */
    SceIoIob *iob; /* 0x58 */
    SceUmd9660Drive *drive; /* 0x5C */
} SceUmd9660File;
typedef char chk_SceUmd9660File[(sizeof(SceUmd9660File) == 0x60) ? 1 : -1];

types.SceUmd9660Mgr:
/* g_umd9660Mgr */
typedef struct {
    SceUID semaId; /* 0x00: "SceUmd9660Mgr" */
    u32 unk4; /* 0x04 */
    u32 unk8; /* 0x08 */
    u32 unkC; /* 0x0C */
    u32 unk10; /* 0x10 */
    s32 maxFiles; /* 0x14 */
    SceUID heapId; /* 0x18 */
} SceUmd9660Mgr;

types.SceUmdDiscInfo:
/* sceUmdGetDiscInfo result */
typedef struct {
    u32 size; /* 0x0 */
    u32 type; /* 0x4 */
    u32 unk8; /* 0x8 */
} SceUmdDiscInfo;

types.SceUmdDrive:
/* umdman drive (sceUmdManGetUmdDrive), only the fields umd9660 touches */
typedef struct SceUmdDrive {
    struct { s8 driveId; u8 pad1[0x7]; u32 unk8; } *ataDrive; /* 0x00 */
    s32 unk4; /* 0x04 */
    u32 unk8; /* 0x08 */
    s32 unkC; /* 0x0C */
    s32 unk10; /* 0x10: 0x10 = UMD, 0x20 = not */
    u8 pad14[0x14];
    s32 unk28; /* 0x28 */
    s32 unk2C; /* 0x2C */
    s32 unk30; /* 0x30 */
    s32 unk34; /* 0x34 */
    s32 unk38; /* 0x38 */
    s32 unk3C; /* 0x3C */
} SceUmdDrive;

types.SceUmdLbnParam:
